def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or not isfinite(volume) or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or not isfinite(v) or v <= 0 or not sites:
            return 0.0
        volume = v * len(sites)
    total = 0.0
    for site in sites:
        p = ep.get(site.get('element')) or {}
        r = p.get('covalent_radius_A')
        o = site.get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if r is not None and isfinite(r) and r > 0:
            total += o * r * r * r
    return 4.0 * pi * total / (3.0 * volume)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    n = len(sites)
    radii = [(ep.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [1.0 if x.get('occupancy') is None else max(0.0, x.get('occupancy')) for x in sites]
    near = [inf] * n
    for b in s.get('neighbors') or []:
        i, j = b.get('i', -1), b.get('j', -1)
        d = b.get('distance_A')
        if not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        a, c = radii[i], radii[j]
        if occ[i] <= 0 or occ[j] <= 0 or a is None or c is None:
            continue
        if not isfinite(a) or not isfinite(c) or a <= 0 or c <= 0:
            continue
        near[i] = min(near[i], d / (a + c))
    z = sum(occ[i] for i in range(n) if isfinite(near[i]))
    return sum(occ[i] * near[i] for i in range(n) if isfinite(near[i])) / z if z > 0 else 0.0

