        return 0.0
    random_unlike = 1.0 - sum((v / z) ** 2 for v in counts.values())
    unlike = 0.0
    norm = 0.0
    for b in s.get('neighbors') or []:
        i, j = b.get('i', -1), b.get('j', -1)
