        d = b.get('distance_A')
        if not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if open_shell[i] <= 0 or open_shell[j] <= 0:
            continue
        a, c = radii[i], radii[j]
        if a is None or c is None or not isfinite(a) or not isfinite(c) or a <= 0 or c <= 0:
            continue
        u = d / (a + c)
        total += occ[i] * occ[j] * open_shell[i] * open_shell[j] * exp(2.0 - 2.0 * u * u)
