    if volume is None or not isfinite(volume) or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or not isfinite(v) or v <= 0 or not sites:
            return 0.0
        volume = v * len(sites)
    total = 0.0
    for site in sites:
        p = ep.get(site.get('element')) or {}
        v = p.get('valence_electrons')
        o = site.get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if v is not None and isfinite(v) and v >= 0:
            total += o * v
    return total / volume

def feature(s):
