    n = len(sites)
    z = sum(occ)
    if z <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b.get('i', -1), b.get('j', -1)
        d = b.get('distance_A')
        if not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        a, c, x, y = radii[i], radii[j], ion[i], ion[j]
        if any(v is None for v in [a, c, x, y]):
            continue
        if not all(isfinite(v) for v in [a, c, x, y]) or min(a, c, x, y) <= 0:
            continue
        term = 1.5 * x * y / (x + y) * (a * c) ** 3 / (d ** 6 + (a + c) ** 6)
        total += occ[i] * occ[j] * term
