def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    props = [ep.get(x.get('element')) or {} for x in sites]
    radii = [p.get('covalent_radius_A') for p in props]
    open_shell = []
    for p in props:
        q = p.get('pymatgen_valence_subshell')
        h = 0.0
        if q is not None and len(q) == 2:
            l, v = q[0], q[1]
            if l is not None and v is not None and isfinite(l) and isfinite(v) and l >= 2:
                capacity = 2.0 * (2.0 * l + 1.0)
                h = max(0.0, min(v, capacity - v))
        open_shell.append(h)
    occ = [1.0 if x.get('occupancy') is None else max(0.0, x.get('occupancy')) for x in sites]
    n = len(sites)
    z = sum(occ)
    if z <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i, j = b.get('i', -1), b.get('j', -1)
        d = b.get('distance_A')
        if not (0 <= i < n and 0 <= j < n) or d is None or not isfinite(d) or d <= 0:
            continue
        if open_shell[i] <= 0 or open_shell[j] <= 0:
            continue
        a, c = radii[i], radii[j]
        if a is None or c is None or not isfinite(a) or not isfinite(c) or a <= 0 or c <= 0:
            continue
        u = d / (a + c)
        total += occ[i] * occ[j] * open_shell[i] * open_shell[j] * exp(2.0 - 2.0 * u * u)
    return total / (2.0 * z)
